// ui/animal-count-field.js
var _shownSession;
var _shownCount;
function fieldEl() {
  return document.getElementById("tbNumAnimals");
}
function show(input) {
  _shownSession = state.session;
  _shownCount = getTrackerNumAnimals();
  input.value = _shownCount != null ? String(_shownCount) : "";
}
function wireAnimalCountField() {
  var input = fieldEl();
  if (!input) return;
  function commit() {
    var raw = input.value.trim();
    var n4 = raw === "" ? null : Number(raw);
    if (input.validity.badInput || n4 !== null && (!Number.isInteger(n4) || n4 < 1)) {
      show(input);
      setStatus("Animals must be a whole number, 1 or more, or blank to auto-detect", "error");
      return;
    }
    if (!state.session) {
      show(input);
      setStatus("Load a session first: the animal count is saved with it", "warning");
      return;
    }
    setTrackerNumAnimals(n4);
  }
  show(input);
  onTrackerNumAnimalsChange(function() {
    show(input);
  });
  input.addEventListener("change", commit);
  input.addEventListener("keydown", function(e) {
    if (e.key === "Enter") {
      e.preventDefault();
      input.blur();
    } else if (e.key === "Escape") {
      e.preventDefault();
      e.stopPropagation();
      show(input);
      input.blur();
    }
  });
}
function syncAnimalCountField() {
  var input = fieldEl();
  if (!input) return;
  if (state.session === _shownSession && getTrackerNumAnimals() === _shownCount) return;
  if (document.activeElement === input) return;
  show(input);
}

// ui/track-range-modal.js
var DEFAULT_RANGE_LENGTH = 100;
function toDisplay(frameIdx) {
  return frameIdx + 1;
}
function toIndex(displayValue) {
  return displayValue - 1;
}
function showTrackRangeModal(opts) {
  var onTracked = opts && opts.onTracked || null;
  var session = getActiveSession();
  if (!session || !session.cameras || session.cameras.length === 0) {
    setStatus("No session with cameras loaded", "error");
    return;
  }
  var bounds = trackableFrameBounds(session);
  if (!bounds) {
    setStatus("No frames to track", "error");
    return;
  }
  var cur = Math.min(Math.max(state.currentFrame || 0, bounds.min), bounds.max);
  var defStart = cur;
  var defEnd = Math.min(bounds.max, cur + DEFAULT_RANGE_LENGTH - 1);
  var animals = getTrackerNumAnimals();
  var overlay = document.createElement("div");
  overlay.className = "multi-frame-modal-overlay";
  var modal = document.createElement("div");
  modal.className = "multi-frame-modal";
  modal.innerHTML = '<h3>Track Frame Range</h3><p>Assign identities across a contiguous span of frames. Tracking restarts at the first frame of the range and carries no history in from before it, so identities inside the range are assigned independently of the frames around it.</p><div class="range-slider-container">  <div class="range-slider-track"></div>  <div class="range-slider-fill" id="trackRangeFill"></div>  <input type="range" id="trackRangeSliderStart" min="' + bounds.min + '" max="' + bounds.max + '" value="' + defStart + '">  <input type="range" id="trackRangeSliderEnd" min="' + bounds.min + '" max="' + bounds.max + '" value="' + defEnd + '"></div><div class="track-range-bounds">  <span>' + toDisplay(bounds.min).toLocaleString() + "</span>  <span>" + toDisplay(bounds.max).toLocaleString() + '</span></div><div class="track-range-fields"><label class="track-range-field"><span>Start frame</span><input type="number" id="trackRangeStart" step="1" min="' + toDisplay(bounds.min) + '" max="' + toDisplay(bounds.max) + '" value="' + toDisplay(defStart) + '"></label><label class="track-range-field"><span>End frame</span><input type="number" id="trackRangeEnd" step="1" min="' + toDisplay(bounds.min) + '" max="' + toDisplay(bounds.max) + '" value="' + toDisplay(defEnd) + '"></label><label class="track-range-field"><span>Animals</span><input type="number" id="trackRangeAnimals" step="1" min="1" placeholder="auto" value="' + (animals != null ? animals : "") + '"></label></div><div class="track-range-summary" id="trackRangeSummary"></div><div class="modal-error" id="trackRangeError"></div><div class="modal-actions"><button id="trackRangeCancel">Cancel</button><button class="primary" id="trackRangeContinue">Continue</button></div>';
  overlay.appendChild(modal);
  document.body.appendChild(overlay);
  var startInput = modal.querySelector("#trackRangeStart");
  var endInput = modal.querySelector("#trackRangeEnd");
  var animalsInput = modal.querySelector("#trackRangeAnimals");
  var summaryEl = modal.querySelector("#trackRangeSummary");
  var errorEl = modal.querySelector("#trackRangeError");
  var continueBtn = modal.querySelector("#trackRangeContinue");
  var sliderStart = modal.querySelector("#trackRangeSliderStart");
  var sliderEnd = modal.querySelector("#trackRangeSliderEnd");
  var sliderFill = modal.querySelector("#trackRangeFill");
  function readForm() {
    var s = toIndex(parseInt(startInput.value, 10));
    var e = toIndex(parseInt(endInput.value, 10));
    if (!isFinite(s) || !isFinite(e)) {
      return { error: "Enter a start and end frame." };
    }
    if (s < bounds.min || e < bounds.min || s > bounds.max || e > bounds.max) {
      return {
        error: "Frames must be between " + toDisplay(bounds.min).toLocaleString() + " and " + toDisplay(bounds.max).toLocaleString() + "."
      };
    }
    if (e < s) return { error: "The end frame must not be before the start frame." };
    var raw = animalsInput.value.trim();
    var n4 = null;
    if (raw !== "") {
      n4 = parseInt(raw, 10);
      if (!isFinite(n4) || n4 < 1) return { error: "Animals must be 1 or more, or blank for auto-detect." };
    }
    return { start: s, end: e, animals: n4, error: null };
  }
  function plural3(n4, word) {
    return n4.toLocaleString() + " " + word + (n4 === 1 ? "" : "s");
  }
  function updateSliderFill() {
    var span = bounds.max - bounds.min;
    var lo = parseInt(sliderStart.value, 10);
    var hi = parseInt(sliderEnd.value, 10);
    var leftPct = span > 0 ? (lo - bounds.min) / span * 100 : 0;
    var rightPct = span > 0 ? (hi - bounds.min) / span * 100 : 100;
    sliderFill.style.left = leftPct + "%";
    sliderFill.style.width = Math.max(0, rightPct - leftPct) + "%";
  }
  function refresh() {
    var f = readForm();
    errorEl.textContent = f.error || "";
    continueBtn.disabled = !!f.error;
    summaryEl.textContent = f.error ? "" : plural3(f.end - f.start + 1, "frame") + " \xB7 " + (f.animals != null ? plural3(f.animals, "animal") : "animal count auto-detected");
    updateSliderFill();
  }
  function onSliderInput(which) {
    var lo = parseInt(sliderStart.value, 10);
    var hi = parseInt(sliderEnd.value, 10);
    if (lo > hi) {
      if (which === "start") sliderStart.value = hi;
      else sliderEnd.value = lo;
    }
    startInput.value = toDisplay(parseInt(sliderStart.value, 10));
    endInput.value = toDisplay(parseInt(sliderEnd.value, 10));
    refresh();
  }
  function syncSlidersFromInputs() {
    var f = readForm();
    if (f.error) {
      refresh();
      return;
    }
    sliderStart.value = Math.min(Math.max(f.start, bounds.min), bounds.max);
    sliderEnd.value = Math.min(Math.max(f.end, bounds.min), bounds.max);
    refresh();
  }
  function close() {
    document.removeEventListener("keydown", onKey);
    overlay.remove();
  }
  async function proceed() {
    var f = readForm();
    if (f.error) {
      refresh();
      return;
    }
    setTrackerNumAnimals(f.animals);
    close();
    var res = await trackFrameRange(f.start, f.end);
    if (res && res.ok && res.end != null && onTracked) onTracked(res.end);
  }
  function onKey(e) {
    if (e.key === "Escape") {
      e.preventDefault();
      close();
    } else if (e.key === "Enter") {
      e.preventDefault();
      proceed();
    }
  }
  document.addEventListener("keydown", onKey);
  animalsInput.addEventListener("input", refresh);
  [startInput, endInput].forEach(function(el3) {
    el3.addEventListener("input", syncSlidersFromInputs);
  });
  sliderStart.addEventListener("input", function() {
    onSliderInput("start");
  });
  sliderEnd.addEventListener("input", function() {
    onSliderInput("end");
  });
  modal.querySelector("#trackRangeCancel").addEventListener("click", close);
  continueBtn.addEventListener("click", proceed);
  overlay.addEventListener("click", function(e) {
    if (e.target === overlay) close();
  });
  refresh();
  startInput.focus();
  startInput.select();
}

