function condenseMissingFrames(frames) {
  if (frames.length === 0) return "";
  frames.sort(function(a, b) {
    return a - b;
  });
  var ranges = [];
  var start = frames[0];
  var end = frames[0];
  for (var i = 1; i < frames.length; i++) {
    if (frames[i] === end + 1) {
      end = frames[i];
    } else {
      ranges.push(start === end ? start.toLocaleString("en-US") : start.toLocaleString("en-US") + "\u2013" + end.toLocaleString("en-US"));
      start = frames[i];
      end = frames[i];
    }
  }
  ranges.push(start === end ? start.toLocaleString("en-US") : start.toLocaleString("en-US") + "\u2013" + end.toLocaleString("en-US"));
  return ranges.join("; ");
}
function showTriangulateMultiFrameModal() {
  if (!state.session) {
    setStatus("No session loaded", "warning");
    return;
  }
  if (!sessionHasCalibration()) {
    showCalibrationRequiredPopup();
    return;
  }
  if (state.session.cameras.length < 2) {
    setStatus("Need at least 2 cameras for triangulation", "warning");
    return;
  }
  var overlay = document.createElement("div");
  overlay.className = "multi-frame-modal-overlay";
  var modal = document.createElement("div");
  modal.className = "multi-frame-modal";
  var maxFrame = state.totalFrames - 1;
  var viewsList = '<ul class="modal-view-list">';
  for (var ci = 0; ci < state.session.cameras.length; ci++) {
    viewsList += "<li>" + state.session.cameras[ci].name + "</li>";
  }
  viewsList += "</ul>";
  modal.innerHTML = '<h3>Choose Frames for Triangulation</h3><div class="range-slider-container">  <div class="range-slider-track"></div>  <div class="range-slider-fill" id="tfSliderFill"></div>  <input type="range" id="tfRangeStart" min="0" max="' + maxFrame + '" value="0">  <input type="range" id="tfRangeEnd" min="0" max="' + maxFrame + '" value="' + maxFrame + '"></div><div class="modal-range-row"><div class="frame-inputs-row">  <label>Start</label>  <input type="number" id="tfInputStart" min="1" max="' + (maxFrame + 1) + '" value="1">  <span class="separator">\u2014</span>  <label>End</label>  <input type="number" id="tfInputEnd" min="1" max="' + (maxFrame + 1) + '" value="' + (maxFrame + 1) + '"></div><div class="modal-views-section">  <label>Cameras</label>' + viewsList + '</div></div><div class="multi-frame-error" id="tfError" style="display:none;"></div><div class="multi-frame-progress" id="tfProgress" style="display:none;">  <div class="progress-label" id="tfProgressLabel">0 / 0 frames</div>  <div class="progress-bar-track"><div class="progress-bar-fill" id="tfProgressFill" style="width:0%"></div></div></div><div class="modal-actions" id="tfActions">  <button id="tfCancel">Cancel</button>  <button class="primary" id="tfContinue">Continue</button></div>';
  overlay.appendChild(modal);
  document.body.appendChild(overlay);
  var rangeStart = document.getElementById("tfRangeStart");
  var rangeEnd = document.getElementById("tfRangeEnd");
  var inputStart = document.getElementById("tfInputStart");
  var inputEnd = document.getElementById("tfInputEnd");
  var sliderFill = document.getElementById("tfSliderFill");
  function updateSliderFill() {
    var s = parseInt(rangeStart.value);
    var e = parseInt(rangeEnd.value);
    var max = parseInt(rangeStart.max) || 1;
    var leftPct = s / max * 100;
    var rightPct = e / max * 100;
    sliderFill.style.left = leftPct + "%";
    sliderFill.style.width = rightPct - leftPct + "%";
  }
  function syncSliders() {
    var s = parseInt(rangeStart.value);
    var e = parseInt(rangeEnd.value);
    if (s > e) {
      rangeStart.value = e;
      s = e;
    }
    inputStart.value = s + 1;
    inputEnd.value = e + 1;
    updateSliderFill();
    document.getElementById("tfError").style.display = "none";
  }
  rangeStart.addEventListener("input", syncSliders);
  rangeEnd.addEventListener("input", syncSliders);
  inputStart.addEventListener("change", function() {
    var v = parseInt(inputStart.value) - 1;
    if (isNaN(v) || v < 0) v = 0;
    if (v > parseInt(rangeEnd.value)) v = parseInt(rangeEnd.value);
    if (v > maxFrame) v = maxFrame;
    rangeStart.value = v;
    syncSliders();
  });
  inputEnd.addEventListener("change", function() {
    var v = parseInt(inputEnd.value) - 1;
    if (isNaN(v) || v < 0) v = 0;
    if (v < parseInt(rangeStart.value)) v = parseInt(rangeStart.value);
    if (v > maxFrame) v = maxFrame;
    rangeEnd.value = v;
    syncSliders();
  });
  updateSliderFill();
  document.getElementById("tfCancel").addEventListener("click", function() {
    overlay.remove();
  });
  document.getElementById("tfContinue").addEventListener("click", function() {
    var startFrame = parseInt(inputStart.value);
    var endFrame = parseInt(inputEnd.value);
    if (isNaN(startFrame) || isNaN(endFrame) || startFrame > endFrame) {
      return;
    }
    var missingFrames = [];
    for (var f = startFrame; f <= endFrame; f++) {
      var frameGroupsList = state.session.instanceGroups.get(f);
      if (!frameGroupsList || frameGroupsList.length === 0) {
        missingFrames.push(f);
      }
    }
    if (missingFrames.length > 0) {
      var errorEl = document.getElementById("tfError");
      if (missingFrames.length === 1) {
        errorEl.textContent = "Frame " + (missingFrames[0] + 1).toLocaleString("en-US") + " does not have identity assignment.";
      } else {
        errorEl.textContent = "Frames [" + condenseMissingFrames(missingFrames.map(function(f2) {
          return f2 + 1;
        })) + "] do not have identity assignment.";
      }
      errorEl.style.display = "block";
      return;
    }
    document.getElementById("tfError").style.display = "none";
    document.getElementById("tfActions").style.display = "none";
    document.getElementById("tfProgress").style.display = "block";
    rangeStart.disabled = true;
    rangeEnd.disabled = true;
    inputStart.disabled = true;
    inputEnd.disabled = true;
    runMultiFrameTriangulation(startFrame, endFrame, overlay);
  });
}
async function runMultiFrameTriangulation(startFrame, endFrame, overlayEl) {
  var totalFrames = endFrame - startFrame + 1;
  var progressLabel = document.getElementById("tfProgressLabel");
  var progressFill = document.getElementById("tfProgressFill");
  var result2 = await triangulateMultiFrameInstances(startFrame, endFrame, function(completed, total) {
    var pct = Math.round(completed / total * 100);
    if (progressLabel) progressLabel.textContent = completed.toLocaleString("en-US") + " / " + total.toLocaleString("en-US") + " frames";
    if (progressFill) progressFill.style.width = pct + "%";
  });
  drawAllOverlays(state.currentFrame);
  update3DViewport(state.currentFrame);
  if (viewport3d) viewport3d.fitToScene();
  var avgError = result2.totalErrors.length > 0 ? (result2.totalErrors.reduce(function(a, b) {
    return a + b;
  }, 0) / result2.totalErrors.length).toFixed(2) : "N/A";
  if (progressLabel) {
    progressLabel.textContent = "Done \u2014 triangulated " + result2.triangulated.toLocaleString("en-US") + " frames (" + result2.totalGroups.toLocaleString("en-US") + " groups, avg error: " + avgError + "px)";
  }
  var actionsEl = document.getElementById("tfActions");
  if (actionsEl) {
    actionsEl.innerHTML = '<button class="primary" id="tfClose">Close</button>';
    actionsEl.style.display = "flex";
    document.getElementById("tfClose").addEventListener("click", function() {
      overlayEl.remove();
    });
  }
  setStatus("Multi-frame triangulation complete: " + result2.triangulated.toLocaleString("en-US") + "/" + totalFrames.toLocaleString("en-US") + " frames, avg error: " + avgError + "px", "success");
  if (timeline) {
    for (var [fIdx] of state.triangulationResults) {
      timeline.setFrameModified(fIdx, frameHasGroupedUserInstances(fIdx));
    }
    timeline.refreshTracks(state.session);
  }
}
async function exportLabels() {
  if (!state.session) {
    setStatus("No session to export", "error");
    return;
  }
  var session = state.session;
  var loader = session.lazyLoader;
  var totalFrames = loader ? loader.nFrames : session.frameGroups.size;
  var header = {
    skeleton: {
      name: session.skeleton.name,
      nodes: session.skeleton.nodes,
      edges: session.skeleton.edges
    },
    cameras: session.cameras.map(function(c) {
      return { name: c.name, matrix: c.matrix, dist: c.dist, rvec: c.rvec, tvec: c.tvec, size: c.size };
    }),
    tracks: session.tracks
  };
  var writer = null;
  var parts = null;
  var enc = new TextEncoder();
  var written = 0;
  async function emit(str) {
    written += str.length;
    if (writer) await writer.write(enc.encode(str));
    else parts.push(str);
  }
  if (typeof window.showSaveFilePicker === "function") {
    try {
      var handle = await window.showSaveFilePicker({
        suggestedName: "labels_export.json",
        types: [{ description: "JSON", accept: { "application/json": [".json"] } }]
      });
      writer = await handle.createWritable();
    } catch (e) {
      if (e && e.name === "AbortError") {
        setStatus("Export cancelled", "warning");
        return;
      }
      writer = null;
    }
  }
  if (!writer) {
    var BIG = 2e4;
    var fsaHintJson = fileSystemAccessHint();
    if (totalFrames > BIG && !window.confirm(
      "This project has " + totalFrames.toLocaleString() + " frames. Without a save-file picker the whole JSON export must be built in memory, which may crash the tab." + (fsaHintJson ? "\n\n" + fsaHintJson : "") + "\n\nExport anyway?"
    )) {
      setStatus("Export cancelled", "warning");
      return;
    }
    parts = [];
  }
  showLoading("Exporting labels...");
  try {
    var head = JSON.stringify(header, null, 2);
    await emit(head.slice(0, head.length - 2) + ',\n  "frames": {');
    var first = true;
    var nFrames = 0;
    await sweepLazyFrameWindows(session, async function(frameIdx, fg) {
      if (!fg) return;
      var frameData = {};
      var any = false;
      for (var [camName, instances] of fg.instances) {
        frameData[camName] = instances.map(function(inst) {
          return {
            // JSON boundary: must emit the legacy boxed [[x,y]|null] shape.
            points: inst.toPointsArray(),
            trackIdx: inst.trackIdx,
            type: inst.type,
            score: inst.score,
            modified: inst.modified
          };
        });
        any = true;
      }
      if (!any) return;
      await emit((first ? "\n    " : ",\n    ") + JSON.stringify(String(frameIdx)) + ": " + JSON.stringify(frameData));
      first = false;
      nFrames++;
    }, {
      onProgress: function(done, tot) {
        showLoading("Exporting labels... " + done.toLocaleString("en-US") + "/" + tot.toLocaleString("en-US") + " frames");
      }
    });
    await emit("\n  }\n}\n");
    if (writer) {
      await writer.close();
    } else {
      var blob = new Blob(parts, { type: "application/json" });
      var url = URL.createObjectURL(blob);
      var a = document.createElement("a");
      a.href = url;
      a.download = "labels_export.json";
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      setTimeout(function() {
        URL.revokeObjectURL(url);
      }, 1e3);
    }
    hideLoading();
    setStatus("Labels exported \u2014 " + nFrames.toLocaleString() + " frames, " + (written / 1e6).toFixed(1) + " MB", "success");
  } catch (err) {
    hideLoading();
    try {
      if (writer) await writer.close();
    } catch (e) {
    }
    console.error("[exportLabels] failed:", err);
    setStatus("Label export failed: " + (err && err.message ? err.message : String(err)), "error");
  }
}
