function buildPlacementsRow(plane, views, pool2) {
  var model = planeModel();
  var tr = document.createElement("tr");
  tr.className = "plane-placements-row";
  tr.setAttribute("data-plane-placements-for", String(plane.id));
  var td = document.createElement("td");
  td.colSpan = 4;
  var body = document.createElement("div");
  body.className = "plane-placements-body";
  td.appendChild(body);
  var selected = interactionManager ? interactionManager.selectedPlane : null;
  var poolIdx = planeNodeIndices(plane, pool2);
  views.forEach(function(viewName) {
    var inst = model.getInstance(viewName);
    var row2 = document.createElement("div");
    row2.className = "plane-placement-item";
    row2.setAttribute("data-plane-view", viewName);
    if (inst && inst === selected) row2.classList.add("plane-selected");
    var name = document.createElement("span");
    name.className = "plane-placement-view";
    name.textContent = viewName;
    row2.appendChild(name);
    var off = 0, derived = 0;
    for (var i = 0; i < poolIdx.length; i++) {
      if (poolIdx[i] < 0 || !inst) continue;
      if (inst.isNodeNulled(poolIdx[i])) off++;
      else if (inst.isNodeDerived(poolIdx[i])) derived++;
    }
    var meta = document.createElement("span");
    meta.className = "plane-placement-meta";
    var bits = [];
    if (off) bits.push(off + " off");
    if (derived) bits.push(derived + " reprojected");
    meta.textContent = bits.join(", ");
    if (derived) {
      meta.title = derived + " corner(s) here were reprojected from the 3D, not annotated on this view \u2014 drag one to make it count as an observation in the next triangulation";
    }
    row2.appendChild(meta);
    var del = makeDeleteButton(
      'Un-place "' + plane.name + '" from ' + viewName + " (its 2D points are kept, so re-placing restores them)",
      function() {
        unplacePlaneFromView(plane, viewName);
        refreshPlanePanel();
        redraw();
      }
    );
    row2.appendChild(del);
    row2.addEventListener("click", function() {
      if (interactionManager && inst) interactionManager.selectPlane(inst, -1);
      refreshPlanePanel();
      redraw();
    });
    body.appendChild(row2);
  });
  if (plane.triangulation) {
    var t = plane.triangulation;
    var summary = document.createElement("div");
    summary.className = "plane-tri-summary";
    summary.textContent = "3D: " + t.nNodes + "/" + plane.nodeIds.length + " nodes from " + t.views.join(", ") + (t.meanError != null ? " \u2014 mean err " + t.meanError.toFixed(2) + " px" : "");
    summary.title = summary.textContent;
    body.appendChild(summary);
    if (t.nAnchors) {
      var anchors = document.createElement("div");
      anchors.className = "plane-tri-summary plane-anchor-summary";
      anchors.textContent = t.nAnchors + " pinned node(s) held fixed" + (t.anchorMeanError != null ? " \u2014 they reproject " + t.anchorMeanError.toFixed(2) + " px off" : "");
      anchors.title = anchors.textContent;
      body.appendChild(anchors);
    }
    if (plane.planeFit) {
      var f = plane.planeFit;
      var fit = document.createElement("div");
      fit.className = "plane-tri-summary plane-fit-summary";
      fit.textContent = (f.constrained ? "Fitted (constrained) \u2014 normal (" : "Fitted plane \u2014 normal (") + f.normal.map(function(q2) {
        return q2.toFixed(3);
      }).join(", ") + "), was " + f.rms.toFixed(2) + " mm RMS off-plane";
      fit.title = fit.textContent + "\nCentroid (" + f.centroid.map(function(q2) {
        return q2.toFixed(1);
      }).join(", ") + ")";
      body.appendChild(fit);
    }
    var points3d = points3dForPlane(plane, pool2);
    var errors = nodeErrorsForPlane(plane, pool2);
    for (var n4 = 0; n4 < plane.nodeIds.length; n4++) {
      var node = pool2.getNode(plane.nodeIds[n4]);
      var nodeName = node ? node.name : "?";
      var line2 = document.createElement("div");
      line2.className = "plane-tri-node";
      line2.setAttribute("data-plane-node-id", String(plane.nodeIds[n4]));
      var sw = document.createElement("span");
      sw.className = "plane-swatch";
      sw.style.background = node ? node.color : "#888";
      line2.appendChild(sw);
      var nameEl = document.createElement("span");
      nameEl.className = "plane-tri-node-name";
      nameEl.textContent = nodeName;
      line2.appendChild(nameEl);
      var full = nodeName;
      var xyzEl = document.createElement("span");
      xyzEl.className = "plane-tri-node-xyz";
      if (hasPoint3d(points3d, n4)) {
        var q = getPoint3d(points3d, n4);
        xyzEl.textContent = "(" + q[0].toFixed(1) + ", " + q[1].toFixed(1) + ", " + q[2].toFixed(1) + ")";
        full += "  " + xyzEl.textContent;
        line2.appendChild(xyzEl);
        if (errors[n4] != null) {
          var errEl = document.createElement("span");
          errEl.className = "plane-tri-node-err";
          errEl.textContent = errors[n4].toFixed(2) + " px";
          line2.appendChild(errEl);
          full += "  " + errEl.textContent + " reprojection error";
        }
      } else {
        xyzEl.textContent = "\u2014";
        full += "  \u2014 (no 3D yet)";
        line2.appendChild(xyzEl);
      }
      if (node && node.immutable) {
        var pinEl = document.createElement("span");
        pinEl.className = "plane-tri-node-pin";
        pinEl.innerHTML = ICON_PIN.locked;
        line2.appendChild(pinEl);
        full += "  \u2014 pinned (Locked)";
      }
      line2.title = full;
      body.appendChild(line2);
    }
  }
  tr.appendChild(td);
  return tr;
}

